      AND CASE NEW.kind
        WHEN 'allocate' THEN NEW.amount_minor <= d.total_minor - d.credited_minor - (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') - (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') AND NEW.amount_minor <= (p.amount_minor - (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = p.id) - (SELECT coalesce(sum(prf.amount_minor), 0) FROM payment_refunds prf WHERE prf.payment_id = p.id AND prf.status <> 'failed'))
        ELSE (NEW.amount_minor <= (SELECT coalesce(sum(CASE lpa.kind WHEN 'allocate' THEN lpa.amount_minor ELSE -lpa.amount_minor END), 0) FROM payment_allocations lpa JOIN payments lpp ON lpp.id = lpa.payment_id WHERE lpa.document_id = d.id AND lpp.status = 'confirmed' AND lpp.kind = 'payment') + d.credited_minor + (SELECT coalesce(sum(lta.amount_minor), 0) FROM payment_allocations lta JOIN payments ltp ON ltp.id = lta.payment_id WHERE lta.document_id = d.id AND ltp.status = 'confirmed' AND ltp.kind = 'tds' AND lta.kind = 'allocate') - d.total_minor OR EXISTS (SELECT 1 FROM payment_refunds cbr WHERE cbr.payment_id = NEW.payment_id AND cbr.document_id = NEW.document_id AND cbr.amount_minor = NEW.amount_minor
          AND cbr.origin = 'chargeback' AND cbr.reason_code = 'chargeback' AND cbr.status <> 'failed' AND cbr.release_allocation_id IS NULL)) AND NEW.amount_minor <= (SELECT coalesce(sum(CASE pna.kind WHEN 'allocate' THEN pna.amount_minor ELSE -pna.amount_minor END), 0) FROM payment_allocations pna WHERE pna.payment_id = p.id AND pna.document_id = d.id) END) BEGIN SELECT RAISE(ABORT, 'payment_allocations_bounds: a confirmed payment goes onto an issued, live invoice or debit note of its client and currency, never above the balance or the free money of the payment; a release takes back no more than the excess it holds'); END;
